pthread_t thread_id;
void* thread_return;

void* worker_func(void* arg) {
    // Thread routine execution
    return (void*)42;
}

// Creation: (ID_Ptr, Attrs, Func, Arg)
pthread_create(
    &thread_id,
    NULL,
    worker_func,
    NULL
);

// Synchronization: Wait for thread termination
pthread_join(thread_id, &thread_return);

// Check return value: (int)(long)thread_return
// (Status is often checked via error codes on create/join)
